import { createResource } from 'qortex-resource';

const profile = createResource({
  initialData: { name: '', email: '' },
  validate: {
    on: 'blur',
    fields: {
      name: (v) => (!v ? 'Required' : null),
      email: (v) => (!v?.includes('@') ? 'Invalid email' : null),
    },
  },
  source: {
    save: async (draft) => {
      await api.saveProfile(draft);
      return draft;
    },
  },
});

profile.set('name', 'Ada');
profile.set('email', 'ada@example.com');

profile.snapshot.draft;      // { name: 'Ada', email: 'ada@example.com' }
profile.snapshot.isChanged;  // true
profile.snapshot.changedFields; // ['name', 'email']

const ok = await profile.validate();
if (!ok) {
  console.log(profile.snapshot.errors);
}

const result = await profile.save();
// result.ok === true → draft synced to source, isChanged false

const unsub = profile.subscribe((snap) => {
  console.log(snap.isSaving, snap.isChanged);
});

const unsubField = profile.subscribeField('email', () => {
  console.log(profile.field('email').value);
});
